import{a,_ as e,b as i}from"./chunks/about-dialog.tTRgx-Cb.js";import{_ as n,o as t,c as l,a2 as d}from"./chunks/framework.Dx-TCpNt.js";const m=JSON.parse('{"title":"安装与运行","description":"KomaYomi 既可以作为由本地 Node 服务器支撑的浏览器应用运行，也可以作为 Electron 桌面窗口运行。两者使用同一套服务器代码和同一个数据目录。","frontmatter":{"description":"KomaYomi 既可以作为由本地 Node 服务器支撑的浏览器应用运行，也可以作为 Electron 桌面窗口运行。两者使用同一套服务器代码和同一个数据目录。"},"headers":[],"relativePath":"zh/guide/installation.md","filePath":"zh/guide/installation.md","lastUpdated":1794843105000}'),o={name:"zh/guide/installation.md"};function p(r,s,c,h,u,g){return t(),l("div",null,[...s[0]||(s[0]=[d(`<h1 id="安装与运行" tabindex="-1">安装与运行 <a class="header-anchor" href="#安装与运行" aria-label="Permalink to &quot;安装与运行&quot;">​</a></h1><p>KomaYomi 既可以作为<strong>由本地 Node 服务器支撑的浏览器应用</strong>运行，也可以作为 <strong>Electron 桌面窗口</strong>运行。两者使用同一套服务器代码和同一个数据目录。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>你希望应用跑在自己的机器上，读取自己的目录，不需要账号，也不上传任何东西。这一页带你从全新克隆走到第一次打开页面，并说明桌面打包版与浏览器开发服务器的区别。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li><strong>Node.js 20 或更高版本</strong>（服务器 bundle 按 Node 20 构建；仓库的开发环境用的是 Node 22+）。</li><li>npm（随 Node 一起提供）。</li><li>可选：Electron 相关依赖会随 <code>npm install</code> 一起安装。</li></ul><p>没有托管服务，也不需要账号。应用只监听 <code>127.0.0.1</code>。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>在仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="以开发模式运行" tabindex="-1">以开发模式运行 <a class="header-anchor" href="#以开发模式运行" aria-label="Permalink to &quot;以开发模式运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>这会在 <code>http://127.0.0.1:5173</code> 上启动 Vite（如果 5173 被占用，端口可能会变化）。API 由 Vite 中间件插件提供，因此不需要启动第二个进程。</p><h2 id="以桌面应用运行" tabindex="-1">以桌面应用运行 <a class="header-anchor" href="#以桌面应用运行" aria-label="Permalink to &quot;以桌面应用运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p>该命令做三件事：</p><ol><li><code>npm run build</code> —— 类型检查并把前端构建到 <code>dist/</code>。</li><li><code>npm run server:build</code> —— 用 esbuild 把服务器打包为 <code>dist-server/app.mjs</code>。</li><li><code>electron .</code> —— 打开一个窗口，从本地 HTTP 服务器加载打包好的静态文件。</li></ol><p>桌面版数据目录：</p><ul><li>从源码运行（<code>npm run desktop</code>）时，使用仓库文件夹，<code>raw/</code>、<code>data/</code> 和 <code>exports/</code> 与代码放在一起。</li><li>打包版默认使用 Electron <code>userData</code> 目录内的 <code>library</code> 文件夹，并在首次启动时让你选择文件夹。</li><li><code>Ctrl+Shift+D</code> 可切换数据目录（需要重启）。</li><li>环境变量 <code>MANGA_DATA_DIR</code> 会覆盖数据目录。</li><li><code>MANGA_PORT</code> 固定内部端口；否则会选择一个空闲端。</li></ul><h2 id="打包桌面应用" tabindex="-1">打包桌面应用 <a class="header-anchor" href="#打包桌面应用" aria-label="Permalink to &quot;打包桌面应用&quot;">​</a></h2><p>仓库包含 <code>electron-builder.yml</code> 和两个打包脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:win</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Windows x64：在 release/ 下生成 NSIS 安装程序和便携版 .exe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:dir</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 在 release/ 下生成未打包的应用，适合快速冒烟测试</span></span></code></pre></div><p><code>dist:win</code> 会先构建前端和打包后的服务器，然后用 electron-builder 同时生成 <code>nsis</code> 和 <code>portable</code> 两种目标。产物命名为 <code>KomaYomi-&lt;version&gt;-&lt;arch&gt;.exe</code> 和 <code>KomaYomi-&lt;version&gt;-portable.exe</code>。</p><p>包内包含的内容：</p><ul><li>只有 <code>dist/</code>、<code>dist-server/</code>、<code>electron/</code> 和 <code>package.json</code> —— 不会附带 <code>node_modules</code>。</li><li><code>raw/</code>、<code>data/</code> 和 <code>exports/</code> <strong>不会</strong>被打包。打包版会在首次启动时要求选择图库文件夹，并记住该选择。</li></ul><p>当前限制：</p><ul><li>唯一配置的目标是 Windows x64；没有 macOS 或 Linux 打包。</li><li>安装程序未签名，因此 Windows SmartScreen 可能在首次启动时给出警告。</li><li>本仓库还没有完整走过一次打包流程；第一次运行 <code>npm run dist:win</code> 的产物，请当作<strong>未经验证</strong>，测过再信。</li><li>没有自动更新通道。</li></ul><h2 id="构建产物" tabindex="-1">构建产物 <a class="header-anchor" href="#构建产物" aria-label="Permalink to &quot;构建产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>产物</th><th>用途</th></tr></thead><tbody><tr><td><code>npm run build</code></td><td><code>dist/</code></td><td>静态前端。</td></tr><tr><td><code>npm run server:build</code></td><td><code>dist-server/app.mjs</code></td><td>Electron 使用的打包 Node 服务器。</td></tr><tr><td><code>npm run dist:dir</code></td><td><code>release/</code></td><td>用于冒烟测试的未打包 Electron 应用。</td></tr><tr><td><code>npm run dist:win</code></td><td><code>release/</code></td><td>Windows x64 NSIS 安装程序与便携版 <code>.exe</code>（尚未验证）。</td></tr><tr><td><code>npm run preview</code></td><td>—</td><td>用 Vite preview 提供构建后的前端。API 中间件只有开发服务器才有；要用 API，请启动桌面应用或 <code>npm run dev</code>。</td></tr><tr><td><code>npm run typecheck</code></td><td>—</td><td>TypeScript 项目检查。</td></tr></tbody></table><h2 id="数据目录结构" tabindex="-1">数据目录结构 <a class="header-anchor" href="#数据目录结构" aria-label="Permalink to &quot;数据目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/                       # your images (gitignored)</span></span>
<span class="line"><span>  &lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</span></span>
<span class="line"><span>data/</span></span>
<span class="line"><span>  pages/&lt;volume&gt;/&lt;chapter&gt;/0.json     # one page JSON, 0-based index</span></span>
<span class="line"><span>  templates/                          # panel templates and export templates</span></span>
<span class="line"><span>  presets/                            # alignment presets</span></span>
<span class="line"><span>  layouts/*.json                      # declarative layout templates</span></span>
<span class="line"><span>  library.json                        # manual language-directory mapping</span></span>
<span class="line"><span>  cache/thumbs/                       # thumbnail cache (safe to delete)</span></span>
<span class="line"><span>  backups/                            # project import backups (gitignored)</span></span>
<span class="line"><span>exports/                   # generated HTML, PNG, backups, .mnproj (gitignored)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><code>npm run dev</code> 通过 <code>/raw/...</code> 提供图片，通过 <code>/exports/...</code> 提供生成的文件；这两个文件夹都不会被暴露为静态目录列表。</p><figure class="shot"><img src="`+a+'" alt="设置对话框：标注工具显示范围，以及缩略图、导出临时文件、远端图片缓存与自动分格结果的清理按钮"><figcaption>设置：清理缩略图、导出临时文件、远端图片缓存和自动分格结果。清除缓存不影响笔记、标注和对齐；清除分格会按提示保留笔记与批注。</figcaption></figure><h2 id="端口与主机" tabindex="-1">端口与主机 <a class="header-anchor" href="#端口与主机" aria-label="Permalink to &quot;端口与主机&quot;">​</a></h2><ul><li>开发界面：<code>127.0.0.1:5173</code>。</li><li>文档站点（本站）：从 <code>docs/</code> 启动时为 <code>127.0.0.1:5174</code>。</li><li>Electron 窗口连接一个临时的 localhost 端口。</li></ul><figure class="shot"><img src="'+e+'" alt="首次启动的空图库：侧栏显示“＋ 添加漫画”，主区域显示四步导览"><figcaption>首次启动时图库为空：左侧的“＋ 添加漫画”是入口，中间四张卡片概述了使用流程。</figcaption></figure><h2 id="首次运行" tabindex="-1">首次运行 <a class="header-anchor" href="#首次运行" aria-label="Permalink to &quot;首次运行&quot;">​</a></h2><ol><li>按 <code>raw/&lt;volume&gt;/&lt;ja|zh|en&gt;/&lt;chapter&gt;/&lt;pages&gt;</code> 的结构，至少把一个卷放到 <code>raw/</code> 下。</li><li>打开应用。侧边栏会列出卷和话。</li><li>选择一页。首次打开时该页会被自动检测并保存。</li><li>如果某个语言文件夹未被识别，打开卷设置手动映射目录。</li><li>点击顶栏的<strong>关于</strong>按钮，确认版本和当前数据目录，然后再去反馈问题。</li></ol><figure class="shot"><img src="'+i+`" alt="关于对话框：KomaYomi 版本、构建信息与数据目录路径"><figcaption>关于对话框。反馈问题时，版本号和数据目录是首先需要说明的两项信息。</figcaption></figure><p>命名规则以及扫描器接受的语言别名，请参见<a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a>。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>5173 端口被占用。</strong> Vite 会顺延到下一个空闲端口，请以终端打印的地址为准，不要默认还是 5173。</li><li><strong>侧边栏是空的。</strong> <code>raw/</code> 下没有卷，或者文件夹名没被识别。参见<a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a>。</li><li><strong>打包版启动后要求选择文件夹。</strong> 这是正常的：安装包不附带 <code>raw/</code>、<code>data/</code> 和 <code>exports/</code>。</li><li><strong>桌面窗口里改了目录却没生效。</strong> 用 <code>Ctrl+Shift+D</code> 切换数据目录后必须重启，切换不是实时的。</li><li><strong><code>npm run preview</code> 里没有 API。</strong> 该中间件只存在于开发服务器和桌面版，预览模式下页面加载不了图片。</li><li><strong><code>dist:win</code> 尚未验证。</strong> 第一次打包请当作冒烟测试，并在干净机器上记录安装器的实际行为。</li></ul><h2 id="文档站点" tabindex="-1">文档站点 <a class="header-anchor" href="#文档站点" aria-label="Permalink to &quot;文档站点&quot;">​</a></h2><p>文档位于 <code>docs/</code>，有自己独立的依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://127.0.0.1:5174</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # static output in docs/.vitepress/dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # preview the production build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在仓库根目录也可以使用 <code>npm --prefix docs run docs:dev</code>。</p>`,46)])])}const F=n(o,[["render",p]]);export{m as __pageData,F as default};
